mapper.select:
SELECT S.ORDER_ID as orderId, T.TRADE_STATUS as orderStatus, S.PORTFOLIO_ID as portfolioId, PP.PARENT_PORTFOLIO_ID ACT_PORTFOLIO_ID, PP.PORTFOLIO_NAME as portfolioName, case S.PS when '${IE_FLAG_02}' then S.MY_ACCT_NO else S.COUNTER_ACCT_NO end as myAcctNo, case S.PS when '${IE_FLAG_02}' then S.COUNTER_ACCT_NO else S.MY_ACCT_NO end as counterAcctNo, T.PS as payType, S.SETTLE_AMT as settleAmt,
T.PRIN_AMT as prinAmt, T.INT_AMT as intAmt,
S.SETTLE_DATE as settleDate, T.TRADE_ID as tradeId, T.CHL_ID as chlId, FP.FINPROD_NAME as chlName FROM STL_PAY_ORDERS S LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = S.TRADE_ID LEFT JOIN FIN_PRODUCT FP ON T.CHL_ID = FP.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T.IS_CANCEL = #{yesNo_no}
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND S.COUNTER_ACCT_NO = #{counterAcctNo}
AND S.MY_ACCT_NO = #{myAcctNo}
AND T.PS = #{payType}
AND T.TRADE_STATUS IN
#{item}
AND S.SETTLE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')
AND T.PS IN
#{item}
AND T.CHL_ID = #{chlId}
order by S.SETTLE_DATE desc, S.PORTFOLIO_ID

SELECT P.ACCT_NO id, S.ACCT_NAME text FROM PTL_CAPACCT_INFO P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO AND P.CCY = S.CCY
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY = #{ccy}

SELECT P.ACCT_NO id, S.ACCT_NAME text FROM STL_FIN_PRODUCT_ACCT P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO AND P.CCY = S.CCY
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.FINPROD_ID = #{chlId}
AND P.CCY = #{ccy}

SELECT 
    max(SEQNO)
FROM 
    PTL_CASH_POSITION_FLOW


        AND ORDER_ID = #{tradeId}


        AND HODING_TYPE=#{hodeType}
